from catalog.codigos import codigo_desde_nombre



def _asignar(Modelo, queryset):
    usados = set(Modelo.objects.exclude(codigo=None).values_list("codigo", flat=True))
    for obj in queryset.filter(codigo=None).order_by("pk"):
        base, candidato, n = codigo_desde_nombre(obj.nombre), None, 1
        candidato = base
        while candidato in usados:
            n += 1
            candidato = f"{base}_{n}"
        usados.add(candidato)
        Modelo.objects.filter(pk=obj.pk).update(codigo=candidato)


def asignar_codigos(apps, schema_editor):
    """Los registros que ya existían reciben su código a partir del nombre actual."""
    for nombre_modelo in ("TipoLicencia", "TipoNovedad"):
        Modelo = apps.get_model("catalog", nombre_modelo)
        _asignar(Modelo, Modelo.objects.all())
    Documento = apps.get_model("catalog", "TipoDocumento")
    _asignar(Documento, Documento.objects.filter(implementacion=None, es_custom=False))


